import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsOn = cookieStore.get('notifications')?.value !== 'off'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsOn ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsOn ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

